<script setup lang="ts">
import {computed, ref} from 'vue'; import {useRoute, useRouter} from 'vue-router'; import {useSessionStore} from '../stores/session'; import CrmDashboardView from './crm/CrmDashboardView.vue'; import CrmCustomersView from './crm/CrmCustomersView.vue'; import CrmPipelineView from './crm/CrmPipelineView.vue'; import ProductLinesView from './product/ProductLinesView.vue'; import ProductListView from './product/ProductListView.vue'; import WorkItemListView from './product/WorkItemListView.vue'; import ProjectListView from './project/ProjectListView.vue'; import ProjectMilestonesView from './project/ProjectMilestonesView.vue'; import ApprovalCenterView from './approval/ApprovalCenterView.vue'; import ModulePlaceholder from '../components/common/ModulePlaceholder.vue';
type MenuItem = [string, string]; type MenuGroup = {title: string; items: MenuItem[]};
const groups: MenuGroup[] = [{title: '工作台', items: [['wb_my_tasks', '我的任务'], ['wb_okr_perf', '目标与绩效'], ['wb_knowledge', '知识库']]}, {title: '客户与商机', items: [['crm_dashboard', '数据看板'], ['crm_customers', '客户档案'], ['crm_leads', '线索管理'], ['crm_opportunities', '商机管理']]}, {title: '产研管理', items: [['prod_lines', '产品线'], ['prod_versions', '版本迭代'], ['prod_req_tasks', '需求任务'], ['prod_bugs', '缺陷管理']]}, {title: '项目管理', items: [['proj_list', '项目列表'], ['proj_config', '里程碑计划']]}, {title: '财务管理', items: [['finance_overview', '财务概览'], ['finance_invoices', '发票管理'], ['finance_receivables', '应收账款'], ['finance_payables', '应付账款'], ['finance_collection', '收款管理']]}, {title: '协同管理', items: [['approval_center', '审批中心'], ['team_org', '团队组织'], ['system_settings', '系统设置']]}];
const route = useRoute(); const router = useRouter(); const store = useSessionStore(); const collapsed = ref(false); const openTabs = ref([{id: 'wb_my_tasks', title: '我的任务'}]); const activeId = computed(() => String(route.params.viewId || 'wb_my_tasks')); const activeTitle = computed(() => groups.flatMap((group) => group.items).find(([id]) => id === activeId.value)?.[1] || '工作台');
function open(id: string, title: string) { if (!openTabs.value.some((tab) => tab.id === id)) openTabs.value.push({id, title}); router.push(`/app/${id}`); }
</script>
<template><div class="workspace"><aside :class="['sidebar', {collapsed}]"><div class="brand">{{ collapsed ? 'SC' : '师创管理后台' }}</div><nav><section v-for="group in groups" :key="group.title"><h3 v-if="!collapsed">{{ group.title }}</h3><button v-for="item in group.items" :key="item[0]" :class="{active: activeId === item[0]}" :title="item[1]" @click="open(item[0], item[1])">{{ collapsed ? item[1].slice(0, 1) : item[1] }}</button></section></nav><button class="collapse" @click="collapsed = !collapsed">{{ collapsed ? '展开' : '收起侧边栏' }}</button></aside><div class="workspace-main"><header class="topbar"><button class="mobile-menu">☰</button><strong>{{ activeTitle }}</strong><div class="account"><span>{{ store.user?.name }}</span><button @click="store.logout(); router.push('/login')">退出</button></div></header><div class="tabs"><button v-for="tab in openTabs" :key="tab.id" :class="{active: activeId === tab.id}" @click="router.push(`/app/${tab.id}`)">{{ tab.title }}</button></div><main class="content"><CrmDashboardView v-if="activeId === 'crm_dashboard'" /><CrmCustomersView v-else-if="activeId === 'crm_customers'" /><ProductLinesView v-if="activeId === 'prod_lines'" /><ProductListView v-else-if="activeId === 'prod_versions'" kind="versions" /><ProductListView v-else-if="activeId === 'prod_req_tasks'" kind="requirements" /><WorkItemListView v-else-if="activeId === 'prod_design_tasks'" kind="design" /><WorkItemListView v-else-if="activeId === 'prod_rd_tasks'" kind="dev" /><WorkItemListView v-else-if="activeId === 'prod_bugs'" kind="bug" /><ProjectListView v-else-if="activeId === 'proj_list'" /><ProjectMilestonesView v-else-if="activeId === 'proj_config'" /><ModulePlaceholder v-else-if="activeId === 'wb_my_tasks'" kicker="MY TASKS" title="我的任务" description="工作台任务模块已完成 Vue 页面骨架。" :features="['待办任务','逾期任务','最近更新']" /><ModulePlaceholder v-else-if="activeId === 'wb_okr_perf'" kicker="OKR PERFORMANCE" title="目标与绩效" description="目标与绩效模块已完成 Vue 页面骨架。" :features="['目标进度','绩效概览','团队排名']" /><ModulePlaceholder v-else-if="activeId.startsWith('finance_')" kicker="FINANCE" title="财务模块待修改或删除" description="按当前迁移范围，财务模块暂不迁移，后续根据产品方案决定修改或删除。" :features="['暂不迁移','保留入口','等待产品确认']" /><ApprovalCenterView v-else-if="activeId === 'approval_center'" /><ModulePlaceholder v-else-if="activeId === 'approval_center_old'" kicker="APPROVAL CENTER" title="审批中心" description="审批中心 Vue 页面骨架已迁移。" :features="['待我审批','我发起的','审批记录']" /><ModulePlaceholder v-else-if="activeId === 'team_org'" kicker="TEAM ORGANIZATION" title="团队组织待修改或删除" description="按当前迁移范围，团队组织暂不迁移，后续根据产品方案决定修改或删除。" :features="['暂不迁移','保留入口','等待产品确认']" /><ModulePlaceholder v-else-if="activeId === 'system_settings'" kicker="SYSTEM SETTINGS" title="系统设置待修改或删除" description="按当前迁移范围，系统设置暂不迁移，后续根据产品方案决定修改或删除。" :features="['暂不迁移','保留入口','等待产品确认']" /><ModulePlaceholder v-else-if="activeId === 'wb_knowledge'" kicker="KNOWLEDGE" title="知识库" description="知识库模块已完成 Vue 页面骨架。" :features="['知识目录','最近文档','我的收藏']" /><CrmPipelineView v-else-if="['crm_leads','crm_opportunities','crm_followups','crm_contracts'].includes(activeId)" :kind="activeId === 'crm_leads' ? 'leads' : activeId === 'crm_opportunities' ? 'opportunities' : activeId === 'crm_followups' ? 'followUps' : 'contracts'" /><template v-else><span class="eyebrow">VUE MIGRATION</span><h1>{{ activeTitle }}</h1><p>Vue 应用壳已就绪，业务模块将按计划逐步迁移。</p></template></main></div></div></template>
